dashboard.definition:
{
  "title": "SAP Services",
  "description": "SAP startup service and host agent — authentication events, SSL/TLS failures, and service health",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "title": "Total Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_auth_fail": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_auth_fail"
      },
      "title": "Auth Failures",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_volume_by_type": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_volume_by_type"
      },
      "title": "Event Volume by Service (Normal vs Errors)",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off",
        "legendDisplay": "bottom",
        "seriesColorsByField": {
          "sapstartsrv (normal)": "#0877a6",
          "sapstartsrv (errors)": "#dc4e41",
          "saphostexec (normal)": "#00d4b4",
          "saphostexec (errors)": "#b50101"
        }
      }
    },
    "viz_auth_events": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_auth_events"
      },
      "title": "Sapstartsrv Authentication Events",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_ssl_events": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_ssl_events"
      },
      "title": "SSL Authentication Failure Sources",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Asapstartsrv%22%20is_ssl_event%3D%22true%22%20auth_result%3D%22failure%22%20remote_ip%3D%22%24row.Source%20IP.value%24%22%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_hostexec_severity": {
      "type": "splunk.pie",
      "dataSources": {
        "primary": "ds_hostexec_severity"
      },
      "title": "Host Agent Severity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "showDonutHole": true,
        "backgroundColor": "transparent"
      }
    },
    "viz_rect_r1l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3m": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_ssl_events": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_ssl_events"
      },
      "title": "SSL/TLS Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/integration/#sap-services",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:sapstartsrv\", \"sap:saphostexec\") | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_auth_fail": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" auth_result=\"failure\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_volume_by_type": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:sapstartsrv\", \"sap:saphostexec\") | eval is_error_event = case(sourcetype=\"sap:sapstartsrv\" AND is_auth_event=\"true\" AND auth_result=\"failure\", 1, sourcetype=\"sap:saphostexec\" AND severity IN (\"ERROR\", \"WARNING\"), 1, 1=1, 0) | eval series = case(sourcetype=\"sap:sapstartsrv\" AND is_error_event=1, \"sapstartsrv (errors)\", sourcetype=\"sap:sapstartsrv\", \"sapstartsrv (normal)\", sourcetype=\"sap:saphostexec\" AND is_error_event=1, \"saphostexec (errors)\", sourcetype=\"sap:saphostexec\", \"saphostexec (normal)\") | timechart span=1d count by series"
      }
    },
    "ds_auth_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_auth_event=\"true\" | table _time auth_user remote_ip webmethod auth_result | sort -_time | head 30 | rename auth_user as User remote_ip as \"Remote IP\" webmethod as Method auth_result as Result"
      }
    },
    "ds_ssl_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_ssl_event=\"true\" auth_result=\"failure\" | stats count as failures, dc(auth_user) as users, values(auth_user) as user_list, latest(_time) as last_seen_ts, earliest(_time) as first_seen_ts by remote_ip | eval first_seen = strftime(first_seen_ts, \"%Y-%m-%d %H:%M:%S\") | eval last_seen = strftime(last_seen_ts, \"%Y-%m-%d %H:%M:%S\") | eval span_h = round((last_seen_ts - first_seen_ts)/3600, 1) | sort -failures | head 50 | table remote_ip, failures, users, user_list, first_seen, last_seen, span_h | rename remote_ip as \"Source IP\", failures as \"Failures\", users as \"Distinct Users\", user_list as \"Users Tried\", first_seen as \"First Seen\", last_seen as \"Last Seen\", span_h as \"Activity Span (h)\""
      }
    },
    "ds_hostexec_severity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:saphostexec\" severity=* | stats count by severity | sort -count"
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_kpi_ssl_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:sapstartsrv\" is_ssl_event=\"true\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "display": "fit-to-width",
          "height": 1281,
          "width": 1920,
          "backgroundColor": "#0d1117"
        },
        "structure": [
          {
            "item": "viz_nav_go",
            "type": "block",
            "position": {
              "x": 10,
              "y": 10,
              "w": 120,
              "h": 25
            }
          },
          {
            "item": "viz_kpi_rect_1",
            "type": "block",
            "position": {
              "x": 10,
              "y": 45,
              "w": 620,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_total",
            "type": "block",
            "position": {
              "x": 15,
              "y": 50,
              "w": 610,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_rect_2",
            "type": "block",
            "position": {
              "x": 642,
              "y": 45,
              "w": 620,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_auth_fail",
            "type": "block",
            "position": {
              "x": 647,
              "y": 50,
              "w": 610,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_rect_3",
            "type": "block",
            "position": {
              "x": 1274,
              "y": 45,
              "w": 636,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_ssl_events",
            "type": "block",
            "position": {
              "x": 1279,
              "y": 50,
              "w": 626,
              "h": 130
            }
          },
          {
            "item": "viz_rect_r1l",
            "type": "block",
            "position": {
              "x": 10,
              "y": 197,
              "w": 1900,
              "h": 300
            }
          },
          {
            "item": "viz_volume_by_type",
            "type": "block",
            "position": {
              "x": 15,
              "y": 202,
              "w": 1890,
              "h": 290
            }
          },
          {
            "item": "viz_rect_r3m",
            "type": "block",
            "position": {
              "x": 10,
              "y": 509,
              "w": 1900,
              "h": 400
            }
          },
          {
            "item": "viz_ssl_events",
            "type": "block",
            "position": {
              "x": 15,
              "y": 514,
              "w": 1890,
              "h": 390
            }
          },
          {
            "item": "viz_rect_r3l",
            "type": "block",
            "position": {
              "x": 10,
              "y": 921,
              "w": 940,
              "h": 340
            }
          },
          {
            "item": "viz_auth_events",
            "type": "block",
            "position": {
              "x": 15,
              "y": 926,
              "w": 930,
              "h": 330
            }
          },
          {
            "item": "viz_rect_r3r",
            "type": "block",
            "position": {
              "x": 962,
              "y": 921,
              "w": 948,
              "h": 340
            }
          },
          {
            "item": "viz_hostexec_severity",
            "type": "block",
            "position": {
              "x": 967,
              "y": 926,
              "w": 938,
              "h": 330
            }
          },
          {
            "item": "viz_more_info",
            "type": "block",
            "position": {
              "x": 1770,
              "y": 10,
              "w": 140,
              "h": 25
            }
          }
        ],
        "type": "absolute"
      }
    },
    "options": {},
    "tabs": {
      "items": [
        {
          "label": "New tab",
          "layoutId": "layout_1"
        }
      ]
    }
  }
}
